import React from "react";
import { useNavigate } from "react-router-dom";
import { useTooltip } from "../../../contexts/tooltip.jsx";
import getIcon from "../../../utils/Iconifier.jsx";
import styles from "./Styles/Button.module.scss";
import { useScreenSize } from "../../../contexts/ScreenSizeProvider.jsx";
import { NudgeContainer } from "../InteractionContainers/NudgeContainer.jsx";

const validTypes = [
  "drop",
  "link",
  "text-only",
  "basic_Expand",
  "withlabel",
  "basic_small",
  "article",
  "subtle",
  "rounded",
  "rounded_catalogue_card_end",
  "rounded_catalogue_card_end_with_label",
  "rounded_label",
  "icon_only",
  "featured",
  "rounded_tag",
  "modern",
  "modern_unfilled",
  "code",
  "code_hover", "code_small",
  "AppStore", "ShinyAppStore"
];
export const StandardButton = ({
  label = "no label",
  callback,
  type = "drop",
  tooltip,
  link,
  icon,
  disable = false,
  headertitle = "",
  external = false,
  fillContainer = false,
  nointeractEffects = false,
  forcedarkmode = false,
  styles: customStyles = {}, // <-- new prop for custom inline styles
}) => {
  const screenSize = useScreenSize(); // 'sm' | 'md' | 'lg'
  const isMobile = screenSize === "sm";

  const { showTooltip, hideTooltip } = useTooltip();
  const navigate = useNavigate();
  const safeType = validTypes.includes(type) ? type : "drop";
  const externalIcon = external ? getIcon("external") : null;

  const setButtonClass = () => {
    const baseClass = styles.button;
    const typeClass = styles[safeType] || styles.drop;
    const disabledClass = disable ? styles.disabled : "";
    const fillClass = fillContainer ? styles.fillContainer : "";
    const mobileClass = isMobile ? styles.mobile : "";
    const darkModeClass = forcedarkmode ? styles.forcedarkmode : "";
    return `${baseClass} ${typeClass} ${disabledClass} ${fillClass} ${mobileClass} ${darkModeClass}`.trim();
  };

  const handleClick = () => {
    if (disable) return;

    if (link) {
      const isExternal = /^https?:\/\//.test(link);
      const isEmail = /^mailto:/.test(link);
      const isEmailAddress = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(link);

      if (isExternal) {
        window.open(link, "_blank");
      } else if (isEmail || isEmailAddress) {
        const mailtoLink = isEmail ? link : `mailto:${link}`;
        window.location.href = mailtoLink;
      } else {
        navigate(link);
      }
    }

    if (callback) callback();
  };

  const handleMouseMove = (e) => {
    if (!isMobile && !disable && tooltip) {
      showTooltip(tooltip, e);
    }
  };

  const handleTouchStart = (e) => {
    // Optional: showTooltip on touch if you ever make mobile tooltips
    // Currently we just suppress it
  };

  const handleKeyDown = (e) => {
    if (!disable && (e.key === "Enter" || e.key === " ")) {
      e.preventDefault();
      handleClick();
    }
  };

  const renderContent = () => {
    const Label = label && <span className={styles.label}>{label}</span>;
    const Icon = icon && <span className={styles.icon}>{icon}</span>;

    switch (safeType) {
      case "text-only":
        return (
          <>
            {Icon}
            {Label}
          </>
        );

      case "link":
        return (
          <>
            {Icon}
            {Label}
          </>
        );

      case "code":
        return (
          <>

            <div className={styles.l1}>
              {Icon}
              {Label}
            </div>
            <div className={styles.l2}>
              {Icon}
              {Label}

            </div>
          </>
        );



      case "rounded":
        return (
          <>
            {Icon}

            {/* {Label} */}
          </>
        );
      case "rounded_catalogue_card_end":
        return (
          <>
            {Icon}

            {/* {Label} */}
          </>
        );

      case "featured":
        return (
          <>
            {Label}
            {Icon}
          </>
        );

      case "icon_only":
        return <>{Icon}</>;
      case "basic_Expand":
        return (
          <div className={styles.expandWrapper}>
            {Label}
            {Icon}
          </div>
        );
      case "rounded_label":
        return (
          <>
            <p>
              <span>
                {Icon} {Label}
              </span>
            </p>

            {/* {Label} */}
          </>
        );
      case "article":
        return (
          <div className={styles.expandWrapper}>
            {headertitle && <span>{headertitle}</span>}
            {Icon}
            {Label}
          </div>
        );

      case "subtle":
        return (
          <div className={styles.subtleWrapper}>
            {Icon}
            <p>{Label}</p>
          </div>
        );

      case "withlabel":
        return (
          <div className={styles.expandWrapper}>
            {headertitle && <span>{headertitle}</span>}
            {Label}
            {Icon}
          </div>
        );
      case "code_small":
        return (
          <>
            {Icon}
            {Label}

          </>
        );
      case "AppStore":
        return (
          <>
            {Icon}
            <div className={styles.textColumn}>
              <span className={styles.subLabel}>Download on the</span>
              <span className={styles.mainLabel}>{Label}</span>
            </div>
          </>
        );
      case "ShinyAppStore":
        return (
          <>
            <div className={styles.shine}></div>
            {Icon}
            <div className={styles.textColumn}>
              <span className={styles.subLabel}>Get it on</span>
              <span className={styles.mainLabel}>{Label}</span>
            </div>
          </>
        );
      case "drop":
      default:
        return (
          <>
            {Label}
            {Icon}
          </>
        );
    }
  };

  return (
    // <NudgeContainer>
    <div
      onMouseMove={handleMouseMove}
      onTouchStart={handleTouchStart}
      onMouseLeave={hideTooltip}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      className={`${setButtonClass()} ${!nointeractEffects && "standardMouseOverBounce"
        }`}
      role="button"
      aria-disabled={disable}
      aria-label={label}
      tabIndex={disable ? -1 : 0}
      style={{ position: "relative", ...customStyles }} // <-- merge custom styles here
    >
      {renderContent()}
      {externalIcon && (
        <span className={styles.externalCornerIcon}>{externalIcon}</span>
      )}
    </div>
    // </NudgeContainer>
  );
};
